.notice-demo{position:absolute;left:0;right:0;top:calc(var(--stack-index)*8px);display:grid;grid-template-columns:40px minmax(0,1fr) 30px;align-items:start;gap:11px;min-height:107px;padding:14px 13px;border:1px solid rgba(255,255,255,.12);border-radius:16px;background:linear-gradient(115deg,#1a2024,#13181c);box-shadow:0 9px 20px rgba(0,0,0,.24);transform:translateY(calc(var(--stack-index)*-3px)) scale(calc(1 - var(--stack-index)*.025));transform-origin:top center;transition:transform .28s ease,opacity .28s ease;touch-action:pan-y}
.notice-demo:not(:first-child){pointer-events:none}
.notice-demo-icon{display:grid;place-items:center;width:38px;height:38px;border:1px solid rgba(115,207,164,.2);border-radius:12px;background:rgba(85,182,137,.09);color:#92deb4;font-size:1.1rem}
.notice-demo>div{display:grid;gap:4px;min-width:0}
.notice-demo small{color:#94c9aa;font-size:.59rem;font-weight:740;letter-spacing:.07em}
.notice-demo b{font-size:.83rem;line-height:1.3}
.notice-demo p{margin:0;color:var(--muted);font-size:.72rem;line-height:1.42}
.notice-dismiss{display:grid;place-items:center;width:28px;height:28px;padding:0;border:0;border-radius:9px;background:rgba(255,255,255,.04);color:#b6bdc2;font-size:1.05rem;cursor:pointer}
.notice-dismiss:hover{background:rgba(243,107,104,.12);color:#ff9c97}
.notice-demo.is-dismissed{opacity:0;transform:translateX(-110%) rotate(-4deg)!important;pointer-events:none}
.live-notices{margin-top:25px;padding-top:12px;border-top:1px solid var(--line)}
