.live-notices #notice-list{margin:0}
.news-carousel{display:flex;gap:12px;min-width:0;overflow-x:auto;overscroll-behavior-x:contain;scroll-snap-type:x mandatory;scrollbar-width:none;padding:2px 1px 12px;touch-action:pan-x pan-y}
