html body #ecosystem-track-market-1 .web-live-countdown strong{grid-column:1;min-width:0;max-width:100%;color:#71f0a9;font:800 clamp(1rem,3.2vw,1.35rem)/1.05 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.015em;text-shadow:0 0 9px rgba(87,240,169,.3);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden}
html body #ecosystem-track-market-1 .web-live-clock-note{grid-column:2;max-width:100%;color:#b6c7bd;font-size:.61rem;line-height:1.15;text-align:right;overflow-wrap:anywhere}
html body #ecosystem-track-market-1 .web-live-statebox{display:grid;grid-template-columns:minmax(0,1fr);gap:2px;min-width:0;padding:4px 6px;border:1px solid rgba(222,82,63,.24);border-radius:8px;background:rgba(94,31,29,.17);overflow-wrap:anywhere}
html body #ecosystem-track-market-1 .web-terminal-state{min-width:0;color:#ff8874;font-size:.72rem;line-height:1.2;letter-spacing:.055em;overflow-wrap:anywhere}
html body #ecosystem-track-market-1 .web-terminal-line{min-width:0;color:#d7dbd8;font-size:.69rem;line-height:1.2;overflow-wrap:anywhere}
html body #ecosystem-track-market-1 .web-live-steps{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:3px!important;width:100%!important;min-width:0!important;margin:0!important;padding:0!important;list-style:none!important}
html body #ecosystem-track-market-1 .web-live-steps li{position:relative;min-width:0;padding:9px 2px 0!important;text-align:center;color:#a4ada8;font-size:.63rem!important;line-height:1.15!important;overflow-wrap:anywhere!important;word-break:normal!important}
html body #ecosystem-track-market-1 .web-live-steps li:before{position:absolute;top:1px!important;left:calc(50% - 3px)!important;width:6px!important;height:6px!important;border:1px solid #57e0a0;background:#101715!important;box-shadow:none!important}
html body #ecosystem-track-market-1 .web-live-steps li.done{color:#9ff0b9}
html body #ecosystem-track-market-1 .web-live-steps li.done:before{background:#57e0a0!important}
html body #ecosystem-track-market-1 .web-live-steps li.current{color:#ff9a86}
html body #ecosystem-track-market-1 .web-live-steps li.current:before{border-color:#ed5945;background:#ed5945!important;box-shadow:0 0 7px rgba(237,89,69,.4)!important}
html body #ecosystem-track-market-1 .web-live-detail{display:block;min-width:0;color:#a8b4ae;font-size:.62rem;line-height:1.15;overflow-wrap:anywhere}
html[data-theme="light"] body #ecosystem-track-market-1 .web-live-countdown{background:linear-gradient(120deg,rgba(36,128,75,.10),rgba(255,255,255,.85));border-color:rgba(36,128,75,.32)}
html[data-theme="light"] body #ecosystem-track-market-1 .web-live-eyebrow{color:#315e44}
html[data-theme="light"] body #ecosystem-track-market-1 .web-live-countdown strong{color:#147640;text-shadow:none}
html[data-theme="light"] body #ecosystem-track-market-1 .web-live-clock-note,html[data-theme="light"] body #ecosystem-track-market-1 .web-terminal-line,html[data-theme="light"] body #ecosystem-track-market-1 .web-live-detail{color:#465a4d}
html[data-theme="light"] body #ecosystem-track-market-1 .web-live-statebox{background:rgba(219,76,58,.055)}
@media(max-width:720px){
 html body .app>.main>.content #view-ecosystem #ecosystem-track-market-1 .ecosystem-card.has-live-web-status{padding:10px 12px!important}
 html body #ecosystem-track-market-1 .web-live-dashboard{gap:4px!important}
 html body #ecosystem-track-market-1 .web-live-countdown{padding:4px 5px!important;gap:2px 3px!important}
 html body #ecosystem-track-market-1 .web-live-clock-note{font-size:.59rem!important}
 html body #ecosystem-track-market-1 .web-terminal-state,html body #ecosystem-track-market-1 .web-terminal-line{font-size:.67rem!important}
 html body #ecosystem-track-market-1 .web-live-detail{font-size:.59rem!important}
}
@media(prefers-reduced-motion:reduce){
 html body #ecosystem-track-market-1 .web-live-dashboard,html body #ecosystem-track-market-1 .web-live-dashboard *{scroll-behavior:auto!important;animation:none!important;transition:none!important}
}
/* Counter spacing v2: distribute the existing card height without expanding its footprint. */
html body #ecosystem-track-market-1 .ecosystem-card.has-live-web-status .ecosystem-card-foot{display:flex!important;flex-direction:column!important;justify-content:stretch!important;min-height:0!important}
html body #ecosystem-track-market-1 .ecosystem-card.has-live-web-status .web-live-status{height:100%!important;min-height:0!important}
html body #ecosystem-track-market-1 .web-live-dashboard{height:100%!important;min-height:0!important;grid-template-rows:auto auto minmax(0,1fr) auto!important;align-content:stretch!important;gap:clamp(6px,1.5vh,12px)!important}
html body #ecosystem-track-market-1 .web-live-countdown{min-height:0!important;padding:clamp(7px,1.2vh,12px) clamp(8px,2vw,14px)!important;gap:4px 8px!important;align-content:center!important}
html body #ecosystem-track-market-1 .web-live-statebox{min-height:0!important;align-content:center!important;padding:clamp(6px,1vh,10px) clamp(8px,2vw,12px)!important}
html body #ecosystem-track-market-1 .web-live-steps{align-self:center!important;padding-block:4px!important}
html body #ecosystem-track-market-1 .web-live-detail{align-self:end!important;padding-top:2px!important}
@media(max-width:720px){html body #ecosystem-track-market-1 .web-live-dashboard{gap:clamp(7px,1.5vh,11px)!important}html body #ecosystem-track-market-1 .web-live-countdown{padding:8px 10px!important}html body #ecosystem-track-market-1 .web-live-countdown strong{font-size:clamp(1.3rem,7vw,1.85rem)!important}}
